module multi_pipe_8bit(
    input clk, rst_n, mul_en_in,
    input [7:0] mul_a, mul_b,
    output mul_en_out,
    output [15:0] mul_out
);
// TODO: Please add your solution here
reg [2:0] mul_en_out_reg;
assign mul_en_out = mul_en_out_reg[2];
always@(posedge clk or negedge rst_n) begin
	if(!rst_n) begin
		mul_en_out_reg <= 0;
	end
	else begin
		mul_en_out_reg <= {mul_en_out_reg[1:0], mul_en_in};
	end
end
reg [7:0] mul_a_reg, mul_b_reg;
always@(posedge clk) begin
	if(mul_en_in) begin
		mul_a_reg <= mul_a;
		mul_b_reg <= mul_b;
	end
	else begin
		mul_a_reg <= 0;
		mul_b_reg <= 0;
	end
end
wire [7:0] temp[0:7];
assign temp[0] = (mul_b_reg[0]==1)?mul_a_reg:0;
assign temp[1] = (mul_b_reg[1]==1)?{mul_a_reg[6:0],1'b0}:0;
assign temp[2] = (mul_b_reg[2]==1)?{mul_a_reg[5:0],2'b0}:0;
assign temp[3] = (mul_b_reg[3]==1)?{mul_a_reg[4:0],3'b0}:0;
assign temp[4] = (mul_b_reg[4]==1)?{mul_a_reg[3:0],4'b0}:0;
assign temp[5] = (mul_b_reg[5]==1)?{mul_a_reg[2:0],5'b0}:0;
assign temp[6] = (mul_b_reg[6]==1)?{mul_a_reg[1:0],6'b0}:0;
assign temp[7] = (mul_b_reg[7]==1)?{mul_a_reg[0],7'b0}:0;
reg [15:0] sum[0:3];
always@(posedge clk) begin
	sum[0] <= temp[0]+temp[1];
	sum[1] <= temp[2]+temp[3];
	sum[2] <= temp[4]+temp[5];
	sum[3] <= temp[6]+temp[7];
end
reg [15:0] mul_out_reg;
always@(posedge clk) begin
	mul_out_reg <= sum[0]+sum[1]+sum[2]+sum[3];
end
assign mul_out = (mul_en_out_reg[2])?mul_out_reg:0;
endmodule
